void test_x509_chain_one_anchor_rsa_sha256(void){x509_certificate_view_t root,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_root_der,sizeof(trust_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_leaf_der,sizeof(trust_leaf_der),&leaf));TEST_ASSERT_EQUAL(129,root.rsa_modulus_length);TEST_ASSERT_EQUAL(128,leaf.signature_length);TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));root.subject_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));root.subject_length++;leaf.signature_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,224U));}
void test_x509_tls_identity_policy(void){x509_certificate_view_t root,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_root_der,sizeof(trust_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_leaf_der,sizeof(trust_leaf_der),&leaf));TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260818000000Z",workspace,224U));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"wrong.example.test","20260818000000Z",workspace,224U));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20250101000000Z",workspace,224U));}
void test_x509_chain_two_intermediate_rsa_sha256(void){x509_certificate_view_t root,intermediate,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_root_der,sizeof(aos417_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_int_der,sizeof(aos417_int_der),&intermediate));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_leaf_der,sizeof(aos417_leaf_der),&leaf));TEST_ASSERT_EQUAL(1U,intermediate.basic_constraints_present);TEST_ASSERT_EQUAL(1U,intermediate.basic_constraints_ca);TEST_ASSERT_EQUAL(1U,intermediate.key_usage_present);TEST_ASSERT_EQUAL(1U,intermediate.key_usage_key_cert_sign);TEST_ASSERT_NOT_NULL(root.subject_key_identifier);TEST_ASSERT_NOT_NULL(intermediate.subject_key_identifier);TEST_ASSERT_NOT_NULL(intermediate.authority_key_identifier);TEST_ASSERT_NOT_NULL(leaf.authority_key_identifier);TEST_ASSERT_EQUAL(0U,leaf.basic_constraints_ca);TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));{const uint8_t wrong_ski[]={0U};const uint8_t* saved_ski=intermediate.subject_key_identifier;uint32_t saved_ski_length=intermediate.subject_key_identifier_length;intermediate.subject_key_identifier=wrong_ski;intermediate.subject_key_identifier_length=sizeof(wrong_ski);TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.subject_key_identifier=saved_ski;intermediate.subject_key_identifier_length=saved_ski_length;}{uint8_t root_path_present=root.path_len_present;uint32_t root_path=root.path_len_constraint;root.path_len_present=1U;root.path_len_constraint=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));root.path_len_present=root_path_present;root.path_len_constraint=root_path;}intermediate.basic_constraints_ca=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.basic_constraints_ca=1U;intermediate.key_usage_key_cert_sign=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.key_usage_key_cert_sign=1U;TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate_two(&leaf,&intermediate,&root,"api.example.test","20260819000000Z",workspace,224U));intermediate.subject_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));intermediate.subject_length++;intermediate.signature_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,224U));}

void test_x509_chain_three_two_intermediates_rsa_sha256(void){x509_certificate_view_t root,int2,int1,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos721_root,sizeof(aos721_root),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos721_int2,sizeof(aos721_int2),&int2));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos721_int1,sizeof(aos721_int1),&int1));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos721_leaf,sizeof(aos721_leaf),&leaf));TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_three(&leaf,&int1,&int2,&root,workspace,224U));TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate_three(&leaf,&int1,&int2,&root,"api.example.test","20260819000000Z",workspace,224U));int2.path_len_present=1U;int2.path_len_constraint=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_three(&leaf,&int1,&int2,&root,workspace,224U));int2.path_len_constraint=1U;int1.basic_constraints_ca=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_three(&leaf,&int1,&int2,&root,workspace,224U));int1.basic_constraints_ca=1U;int2.subject_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_three(&leaf,&int1,&int2,&root,workspace,224U));}

void test_x509_extended_key_usage_server_auth(void){x509_certificate_view_t eku,root,leaf;uint32_t workspace[224]={0};TEST_ASSERT_EQUAL(0,x509_certificate_parse(eku_server_certificate,sizeof(eku_server_certificate),&eku));TEST_ASSERT_EQUAL(1U,eku.extended_key_usage_present);TEST_ASSERT_EQUAL(1U,eku.extended_key_usage_server_auth);TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_root_der,sizeof(trust_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(trust_leaf_der,sizeof(trust_leaf_der),&leaf));leaf.extended_key_usage_present=1U;leaf.extended_key_usage_server_auth=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260818000000Z",workspace,224U));leaf.extended_key_usage_server_auth=1U;TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260818000000Z",workspace,224U));}

void test_x509_name_constraints_dns(void){x509_certificate_view_t constraints,root,intermediate,leaf;uint32_t workspace[224]={0};static const uint8_t permitted[]={'e','x','a','m','p','l','e','.', 't','e','s','t'},wrong_permitted[]={'w','r','o','n','g','.', 't','e','s','t'},descendant_permitted[]={'.','e','x','a','m','p','l','e','.', 't','e','s','t'},excluded[]={'b','a','d','.', 'e','x','a','m','p','l','e','.', 't','e','s','t'};TEST_ASSERT_EQUAL(0,x509_certificate_parse(name_constraints_certificate,sizeof(name_constraints_certificate),&constraints));TEST_ASSERT_EQUAL(1U,constraints.name_constraints_present);TEST_ASSERT_EQUAL(1U,constraints.name_constraints_dns_permitted_count);TEST_ASSERT_EQUAL(1U,constraints.name_constraints_dns_excluded_count);TEST_ASSERT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"api.example.test"));TEST_ASSERT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"EXAMPLE.TEST"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"bad.example.test"));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"api.wrong.test"));constraints.name_constraints_dns_permitted[0]=descendant_permitted;constraints.name_constraints_dns_permitted_length[0]=sizeof(descendant_permitted);constraints.name_constraints_dns_excluded_count=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"example.test"));TEST_ASSERT_EQUAL(0,x509_certificate_name_constraints_dns_validate(&constraints,"api.example.test"));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_root_der,sizeof(aos417_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_int_der,sizeof(aos417_int_der),&intermediate));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos417_leaf_der,sizeof(aos417_leaf_der),&leaf));intermediate.name_constraints_present=1U;intermediate.name_constraints_dns_permitted_count=1U;intermediate.name_constraints_dns_permitted[0]=permitted;intermediate.name_constraints_dns_permitted_length[0]=sizeof(permitted);intermediate.name_constraints_dns_excluded_count=1U;intermediate.name_constraints_dns_excluded[0]=excluded;intermediate.name_constraints_dns_excluded_length[0]=sizeof(excluded);TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate_two(&leaf,&intermediate,&root,"api.example.test","20260819000000Z",workspace,224U));intermediate.name_constraints_dns_permitted[0]=wrong_permitted;intermediate.name_constraints_dns_permitted_length[0]=sizeof(wrong_permitted);TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate_two(&leaf,&intermediate,&root,"api.example.test","20260819000000Z",workspace,224U));}

void test_x509_ec_p256_key_and_chain(void){x509_certificate_view_t root,leaf,altered_leaf;uint8_t altered[sizeof(aos753_ecdsa_leaf_der)];uint32_t workspace[ECDSA_P256_WORKSPACE_WORDS]={0};uint32_t saved_length;uint16_t index;TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos753_ecdsa_root_der,sizeof(aos753_ecdsa_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos753_ecdsa_leaf_der,sizeof(aos753_ecdsa_leaf_der),&leaf));TEST_ASSERT_EQUAL(ECDSA_P256_PUBLIC_KEY_LENGTH,root.ec_p256_public_key_length);TEST_ASSERT_EQUAL(0x04U,root.ec_p256_public_key[0]);TEST_ASSERT_EQUAL(0,x509_ec_p256_public_key_validate(&root));TEST_ASSERT_EQUAL(0,x509_ec_p256_public_key_validate(&leaf));TEST_ASSERT_NOT_EQUAL(0,x509_rsa_public_key_validate(&root));TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));for(index=0U;index<sizeof(altered);index++)altered[index]=aos753_ecdsa_leaf_der[index];TEST_ASSERT_EQUAL(0,x509_certificate_parse(altered,sizeof(altered),&altered_leaf));((uint8_t*)altered_leaf.signature)[altered_leaf.signature_length-1U]^=1U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&altered_leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260819000000Z",workspace,ECDSA_P256_WORKSPACE_WORDS));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS-1U));saved_length=root.ec_p256_public_key_length;root.ec_p256_public_key_length--;TEST_ASSERT_NOT_EQUAL(0,x509_ec_p256_public_key_validate(&root));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));root.ec_p256_public_key_length=saved_length;saved_length=leaf.signature_algorithm_length;leaf.signature_algorithm_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));leaf.signature_algorithm_length=saved_length;saved_length=leaf.signature_length;leaf.signature_length--;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_one(&leaf,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));leaf.signature_length=saved_length;}

void test_x509_ecdsa_chain_two_intermediate(void){x509_certificate_view_t root,intermediate,leaf,altered_leaf;uint8_t altered[sizeof(aos769_ecdsa_leaf_der)];uint32_t workspace[ECDSA_P256_WORKSPACE_WORDS]={0};uint32_t saved_path_length;uint8_t saved_ca;uint16_t index;TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos769_ecdsa_root_der,sizeof(aos769_ecdsa_root_der),&root));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos769_ecdsa_intermediate_der,sizeof(aos769_ecdsa_intermediate_der),&intermediate));TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos769_ecdsa_leaf_der,sizeof(aos769_ecdsa_leaf_der),&leaf));TEST_ASSERT_EQUAL(0,x509_ec_p256_public_key_validate(&root));TEST_ASSERT_EQUAL(0,x509_ec_p256_public_key_validate(&intermediate));TEST_ASSERT_EQUAL(0,x509_ec_p256_public_key_validate(&leaf));TEST_ASSERT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate_two(&leaf,&intermediate,&root,"api.example.test","20260819000000Z",workspace,ECDSA_P256_WORKSPACE_WORDS));TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,ECDSA_P256_WORKSPACE_WORDS-1U));for(index=0U;index<sizeof(altered);index++)altered[index]=aos769_ecdsa_leaf_der[index];TEST_ASSERT_EQUAL(0,x509_certificate_parse(altered,sizeof(altered),&altered_leaf));((uint8_t*)altered_leaf.signature)[altered_leaf.signature_length-1U]^=1U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&altered_leaf,&intermediate,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));saved_ca=intermediate.basic_constraints_ca;intermediate.basic_constraints_ca=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));intermediate.basic_constraints_ca=saved_ca;saved_path_length=root.path_len_constraint;root.path_len_constraint=0U;TEST_ASSERT_NOT_EQUAL(0,x509_certificate_chain_validate_two(&leaf,&intermediate,&root,workspace,ECDSA_P256_WORKSPACE_WORDS));root.path_len_constraint=saved_path_length;}

void test_x509_rejects_unknown_critical_extension(void){uint8_t altered[sizeof(aos417_root_der)];x509_certificate_view_t view;uint32_t i;uint8_t found=0U;for(i=0U;i<sizeof(altered);i++)altered[i]=aos417_root_der[i];for(i=0U;i+5U<sizeof(altered);i++){if(altered[i]==0x55U&&altered[i+1U]==0x1dU&&altered[i+2U]==0x0fU&&altered[i+3U]==0x01U&&altered[i+4U]==0x01U&&altered[i+5U]==0xffU){altered[i+2U]=0x7eU;found=1U;break;}}TEST_ASSERT_EQUAL(1U,found);TEST_ASSERT_NOT_EQUAL(0,x509_certificate_parse(altered,sizeof(altered),&view));}

void test_x509_local_example_test_anchor_and_leaf(void){
    x509_certificate_view_t root,leaf;uint32_t workspace[512]={0};
    TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos_tls_test_root_der,aos_tls_test_root_der_len,&root));
    TEST_ASSERT_EQUAL(0,x509_rsa_public_key_validate(&root));
    TEST_ASSERT_EQUAL(0,x509_certificate_parse(aos_tls_test_leaf_der,sizeof(aos_tls_test_leaf_der),&leaf));
    TEST_ASSERT_EQUAL(0,x509_rsa_public_key_validate(&leaf));
    TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"example.com","20260818000000Z",workspace,512U));
    TEST_ASSERT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20260818000000Z",workspace,512U));
    TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"wrong.example.test","20260818000000Z",workspace,512U));
    TEST_ASSERT_NOT_EQUAL(0,x509_certificate_tls_identity_validate(&leaf,&root,"api.example.test","20190101000000Z",workspace,512U));
}

